<?php
declare(strict_types=1);
namespace App\Infrastructure\Persistence\Doctrine\Study;
use App\Domain\Study\ReadModel\CompletedNotebookAnswer;use App\Domain\Study\Repository\NotebookProgressReaderInterface;use App\Infrastructure\Persistence\Doctrine\Performance\Entity\AnswerRecord;use App\Infrastructure\Persistence\Doctrine\Performance\Entity\AttemptRecord;use App\Infrastructure\Persistence\Doctrine\QuestionBank\Entity\QuestionRecord;use Doctrine\ORM\EntityManagerInterface;
final class DoctrineNotebookProgressReader implements NotebookProgressReaderInterface { public function __construct(private readonly EntityManagerInterface $entityManager){} public function completedAnswersForNotebook(string $userId,string $notebookId):array{$rows=$this->entityManager->createQueryBuilder()->select('attempt.questionId AS questionId','answer.optionId AS optionId','answer.elapsedSeconds AS elapsedSeconds','question.correctOptionId AS correctOptionId')->from(AnswerRecord::class,'answer')->innerJoin(AttemptRecord::class,'attempt','WITH','attempt.id = answer.attemptId')->innerJoin(QuestionRecord::class,'question','WITH','question.id = attempt.questionId')->where('attempt.userId = :userId')->andWhere('attempt.notebookId = :notebookId')->andWhere('attempt.completedAt IS NOT NULL')->andWhere('attempt.finalAnswerId = answer.id')->setParameter('userId',$userId)->setParameter('notebookId',$notebookId)->orderBy('attempt.completedAt','DESC')->getQuery()->getArrayResult();return array_map(static fn(array $row):CompletedNotebookAnswer=>new CompletedNotebookAnswer((string)$row['questionId'],isset($row['correctOptionId'])&&$row['optionId']===$row['correctOptionId'],(int)$row['elapsedSeconds']),$rows);} }
